@List.getElem?_map : ∀ {α : Type u_1} {β : Type u_2} {f : α → β} {l : List α} {i : Nat},
  (List.map f l)[i]? = Option.map f l[i]?
@List.map_map : ∀ {β : Type u_1} {γ : Type u_2} {α : Type u_3} {g : β → γ} {f : α → β} {l : List α},
  List.map g (List.map f l) = List.map (g ∘ f) l
@List.length_map : ∀ {α : Type u_1} {β : Type u_2} {as : List α} (f : α → β), (List.map f as).length = as.length
@List.map_congr_left : ∀ {α : Type u_1} {l : List α} {α_1 : Type u_2} {f g : α → α_1},
  (∀ (a : α), a ∈ l → f a = g a) → List.map f l = List.map g l
@List.sum_cons : ∀ {α : Type u_1} [inst : Add α] [inst_1 : Zero α] {a : α} {l : List α}, (a :: l).sum = a + l.sum
@List.sum_nil : ∀ {α : Type u_1} [inst : Add α] [inst_1 : Zero α], [].sum = 0
@List.foldl_cons : ∀ {α : Type u_1} {β : Type u_2} {a : α} {l : List α} {f : β → α → β} {b : β},
  List.foldl f b (a :: l) = List.foldl f (f b a) l
@Preorder.ne_of_gt : ∀ {α : Type u_1} [inst : LE α] [inst_1 : LT α] [LawfulOrderLT α] {a b : α}, a > b → a ≠ b
@Preorder.le_of_lt : ∀ {α : Type u_1} [inst : LE α] [inst_1 : LT α] [LawfulOrderLT α] {a b : α}, a < b → a ≤ b
@Option.map : {α : Type u_1} → {β : Type u_2} → (α → β) → Option α → Option β
@List.mem_cons : ∀ {α : Type u_1} {b : α} {l : List α} {a : α}, a ∈ b :: l ↔ a = b ∨ a ∈ l
IsLinearOrder : (α : Type u_1) → [LE α] → Prop
LawfulOrderLT : (α : Type u_1) → [LT α] → [LE α] → Prop
OrderedRing : (R : Type u_1) → [Semiring R] → [inst : LE R] → [LT R] → [IsPreorder R] → Prop
